```openscad
// T-shaped nut for aluminium extrusion
// Print orientation: flange on the bed (z = 0), neck building up in +Z
// Positioned using the user's coordinates (x -7 .. 7, y -7 .. 7), not centred

// ---------- Dimensions (mm) ----------
flange_width    = 14;   // flange size in Y
flange_thick    = 2.5;  // flange thickness (z = 0 to 2.5)
neck_width      = 7;    // neck size in Y
neck_top_z      = 5.5;  // top of neck (neck runs z = 2.5 to 5.5)
screw_d         = 4.5;  // central screw hole diameter
length_x        = 12;   // part length along X
cut_overlap     = 0.5;  // extra length on cutters to avoid coplanar faces

$fn = 64;

difference() {
    // Upside-down T profile, extruded along X
    translate([-length_x / 2, 0, 0])
        rotate([90, 0, 0])
            linear_extrude(height = length_x)
                polygon(points = [
                    // Flange: rectangle 14 (Y) x 12 (X)
                    [-6, -7], [-6, 7], [6, 7], [6, -7],
                    // Neck: 7 mm wide, sitting on the flange, top at z = 5.5
                    [-3.5, -3.5, neck_top_z],
                    [-3.5,  3.5, neck_top_z],
                    [ 3.5, -3.5, neck_top_z],
                    [ 3.5,  3.5, neck_top_z]
                ]);

    // Vertical screw hole through the centre, past bottom and top faces
    translate([0, 0, -cut_overlap])
        cylinder(d = screw_d, h = flange_thick + (neck_top_z - flange_thick) + 2 * cut_overlap);
}
