// Stiffened cover panel: flat plate with 4 transverse ribs
// Print orientation: plate flat on bed, ribs pointing up (+Z)

// ---------------- Parameters ----------------
plate_len   = 120;   // plate length along X (mm)
plate_wid   = 50;    // plate width along Y (mm)
plate_thk   = 3;     // plate thickness (mm), z = 0..3

rib_count   = 4;     // number of ribs
rib_thk     = 2;     // rib thickness along X (mm)
rib_hgt     = 5;     // rib height above plate (mm), z = 3..8
rib_pitch   = 24;    // centre-to-centre spacing of ribs (mm)
rib_offset  = 24;    // distance of outer ribs from plate ends (mm)

eps         = 0.5;   // overlap for clean booleans (mm)
$fn         = 64;    // curve resolution (no curves here, set per rules)

// ---------------- Derived ----------------
plate_x0 = -plate_len / 2;   // plate left end
plate_x1 = plate_len / 2;    // plate right end

// Check: 5 equal parts -> 4 ribs, pitch = plate_len / 5 = 24 mm
assert(abs(rib_pitch - plate_len / (rib_count + 1)) < 0.001, "Rib pitch must split plate into equal parts");

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_x0, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, centred on origin, running full width along Y
    for (i = [0 : rib_count - 1]) {
        x_c = (i - (rib_count - 1) / 2) * rib_pitch;
        translate([x_c - rib_thk / 2, -plate_wid / 2, plate_thk])
            cube([rib_thk, plate_wid, rib_hgt]);
    }
}
