// Powder measuring scoop - hollow spherical bowl with a flat handle along +X
// Print orientation: bowl bottom on the bed (z = 0), handle on top, opening upward.

$fn = 96;

// ---- Bowl ----
outer_radius   = 12;   // outer radius of the sphere
wall_thickness = 2;    // wall thickness of the hollow bowl
bottom_z       = 0;    // z of the sphere's south pole (touches the bed)
rim_z          = 12;   // z of the rim (equator, lower half only)

// ---- Handle ----
handle_length   = 102; // length along +X (from x = 10 to x = 112)
handle_width    = 8;   // width along Y
handle_thick    = 4;   // thickness along Z (top face flush with rim)
handle_x0       = 10;  // start of handle
handle_x1       = 112; // end of handle

// ---- Misc ----
eps = 0.5;             // cutter overshoot past faces

difference() {
    union() {
        // Lower half of hollow sphere: outer shell down to the equator,
        // with a 2 mm floor under the bottom hemisphere.
        hull() {
            translate([0, 0, bottom_z])
                cylinder(r = outer_radius, h = rim_z - bottom_z);
            translate([0, 0, bottom_z])
                cylinder(r = outer_radius - wall_thickness, h = rim_z + eps);
        }

        // Flat handle running along +X, centred on y = 0
        translate([handle_x0, -handle_width / 2, handle_thick])
            cube([handle_length, handle_width, handle_thick]);
    }

    // Remove the upper half of the outer sphere above the rim (z > 12)
    translate([0, 0, rim_z])
        cylinder(r = outer_radius + 2 * eps, h = eps);
}
