knuckle_d   = 7;     // knuckle diameter
knuckle_h   = 10;    // knuckle height above plate (z = 3.5 to z = 13.5)
knuckle_n   = 5;     // number of segments along +Y edge
knuckle_x0  = -plate_len/2; // first segment centre X
knuckle_y   = plate_wid/2;   // segment base Y
knuckle_z0  = 3.5;   // knuckle bottom Z
pin_d       = 3;     // pin hole diameter

// ---- Helpers ----
eps         = 0.5;   // cutter overshoot past faces
pitch       = 10;    // segment pitch along Y (1st, 3rd, 5th = 30 mm span)
select      = [0, 2, 4]; // segment indices

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders along X axis at selected Y positions
        for (i = select)
            translate([knuckle_x0 + i*pitch, knuckle_y, knuckle_z0])
                cylinder(d = knuckle_d, h = knuckle_h);
    }

    // Pin hole running along the knuckle axis through every knuckle
    translate([knuckle_x0, knuckle_y, knuckle_z0])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = knuckle_h + eps);
