            x0 = -plate_len/2 + i * knuckle_w;
            translate([x0, 15, knuckle_z])
                cylinder(d = knuckle_d, h = knuckle_w);
        }
    }

    // Pin hole running through every knuckle
    translate([-plate_len/2, 15, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps, center = true);
