```openscad
// Tapered riser block - square frustum with a top pocket
// Print orientation: bottom face on the bed (z = 0), building upward.
// Placed at the user's coordinates: x -40 .. 40, y -40 .. 40, z 0 .. 30.

// ---------------- Parameters ----------------
bottom_w     = 80;   // bottom square side length (mm)
bottom_h     = 80;   // bottom square side length (mm)
top_w        = 50;   // top square side length (mm)
top_h        = 50;   // top square side length (mm)
top_z        = 30;   // height of the top face (mm)
pocket_w     = 40;   // pocket square side length (mm)
pocket_d     = 5;    // pocket depth from the top face (mm)
eps          = 0.5;  // overshoot for the cutting shape (mm)

$fn = 64;

// ---------------- Model ----------------
difference() {
    // Square frustum: hull between the bottom and top faces
    hull() {
        translate([-bottom_w / 2, -bottom_h / 2, 0])
            cube([bottom_w, bottom_h, 0]);
        translate([-top_w / 2, -top_h / 2, top_z])
            cube([top_w, top_h, 0]);
