```openscad
// Tapered riser block - square frustum with a top pocket
// Print orientation: bottom face on the bed (z = 0), building upward.
// Placed at the user's coordinates: x -40..40, y -40..40, z 0..30.

// ---------------- Parameters ----------------
base_w     = 80;    // bottom face side length (mm)
top_w      = 40;    // top face side length (mm)
height     = 30;    // overall height (mm)
pocket_w   = 30;    // pocket side length (mm)
pocket_d   = 8;     // pocket depth from top face (mm)
eps        = 0.5;   // overshoot for clean boolean cuts (mm)

// ---------------- Derived ----------------
// 2D hull vertices of the profile drawn in (X, Y), then extruded along Z
base_bl = [-base_w/2, -base_w/2];   // bottom-left corner of base
base_br = [ base_w/2, -base_w/2];   // bottom-right corner of base
top_bl  = [-top_w/2, -top_w/2];     // top left corner of top face
top_br  = [ top_w/2,  top_w/2];     // top right corner of top face

// ---------------- Model ----------------
difference() {
    // Tapered block: hull of the four corner pillars, then trimmed to z = height
    translate([-base_w/2, -base_w/2, 0])
        hull() {
            // lower corners (full height)
            translate([base_bl[0], base_bl[1], 0])
                cube([1, 1, height]);
            translate([base_br[0], base_br[1], 0])
                cube([1, 1, height]);
            // upper corners (extended above the top face)
            translate([top_bl[0], top_bl[1], -eps])
                cube([1, 1, height + 2*eps]);
            translate([top_br[0], top_br[1], -eps])
                cube([1, 1, height + 2*eps]);
        }
        // keep only the volume below z = height
        intersection() {
            translate([0, 0, -height])
                cube([1, 1, 2*height]);
            // the hull itself (now spilling above the top face)
            translate([base_w/2, base_w/2, 0])
                hull() {
                    translate([base_bl[0], base_bl[1], 0])
                        cube([1, 1, height]);
                    translate([base_br[0], base_br[1], 0])
                        cube([1, 1, height]);
                    translate([top_bl[0], top_bl[1], -eps])
                        cube([1, 1, height + 2*eps]);
                    translate([top_br[0], top_br[1], -eps])
                        cube([1, 1, height + 2*eps]);
                }
        }

    // Square pocket cut into the top face, centred on the origin
    translate([-pocket_w/2, -pocket_w/2, height - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}
