// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness   = 3;     // specimen thickness (Z)
total_len   = 120;   // overall length along X (mm)
gauge_w     = 6;     // gauge section width (Y)
gauge_len   = 40;    // gauge section length (X)
grip_w      = 20;    // grip section width (Y)
grip_len    = 25;    // grip section length (X)
trans_len   = 15;    // transition section length (X)
eps         = 0.5;   // cutter overshoot past faces (mm)

$fn = 64;

// ---------- Derived ----------
half_gauge = gauge_len / 2;
half_grip  = grip_len / 2;
// centre of each grip relative to its own local origin
grip_x0    = -(total_len / 2 + half_grip);   // left grip
grip_x1    =  (total_len / 2 - half_grip);   // right grip

// ---------- 2D profile (top face) ----------
module profile() {
    linear_extrude(thickness) {
        union() {
            // left grip
            translate([grip_x0, -grip_w / 2, 0])
                cube([grip_len, grip_w, thickness]);
            // right grip
            translate([grip_x1, -grip_w / 2, 0])
                cube([grip_len, grip_w, thickness]);
            // gauge section
            translate([-half_gauge, -gauge_w / 2, 0])
                cube([gauge_len, gauge_w, thickness]);
            // left transition: grip -> gauge
            translate([-(half_gauge + trans_len) / 2, -grip_w / 2, 0])
                linear_extrude(thickness)
                    polygon(points = [
                        [0, grip_w / 2],
                        [trans_len, grip_w / 2],
                        [trans_len, gauge_w / 2],
                        [0, gauge_w / 2]
                    ]);
            // right transition: gauge -> grip
            translate([(half_gauge + trans_len) / 2, -grip_w / 2, 0])
                linear_extrude(thickness)
                    polygon(points = [
                        [0, grip_w / 2],
                        [-trans_len, grip_w / 2],
                        [-trans_len, gauge_w / 2],
                        [0, gauge_w / 2]
                    ]);
        }
    }
}

profile();
```

