// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 upward

// ---------- Parameters ----------
specimen_t   = 3;     // thickness (Z)
gauge_w      = 6;     // gauge section width (Y)
gauge_l      = 40;    // gauge section length (X)
grip_w       = 20;    // grip section width (Y)
grip_l       = 25;    // grip section length (X)
transition_l = 15;    // transition section length (X)
eps          = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
total_l = 2 * grip_l + gauge_l + 2 * transition_l;   // 120 mm
// Hull uses 2D points (X, Y), then extrudes in Z

// ---------- Model ----------
hull() {
    // Left grip
    translate([-total_l / 2 + grip_l, -specimen_t / 2, 0])
        cube([grip_l, specimen_t, specimen_t]);
    // Right grip
    translate([total_l / 2 - grip_l, -specimen_t / 2, 0])
        cube([grip_l, specimen_t, specimen_t]);

    // Gauge section (overlaps into each transition by eps)
    translate([-gauge_l / 2 - eps, -specimen_t / 2, -eps])
        cube([gauge_l + 2 * eps, specimen_t, specimen_t + 2 * eps]);
}
