// ---------- Parameters ----------
thickness   = 3;     // specimen thickness (Z)
total_len   = 140;   // overall length along X
gauge_w     = 6;     // gauge section width (Y)
gauge_len   = 50;    // gauge section length (X)
grip_w      = 15;    // grip section width (Y)
grip_len    = 35;    // grip section length (X)
trans_len   = 10;    // transition section length (X)
eps         = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
half_gauge = gauge_len / 2;
half_grip  = grip_len / 2;
// centre of each region (grip -> trans -> gauge -> trans -> grip)
region_c = [
    -half_grip,
    half_grip - trans_len,
    half_gauge - half_trans,
    total_len / 2 - half_grip
];
// widths at region centres (grip -> trans -> gauge -> trans -> grip)
region_w = [
    grip_w,
    grip_w,
    gauge_w,
    grip_w,
    grip_w
];

// ---------- Model ----------
difference() {
    // outer shape
    hull() {
        for (i = [0 : 4])
            translate([region_c[i], 0, 0])
                rotate([90, 0, 0])
                    linear_extrude(height = thickness)
                        polygon([[-region_w[i] / 2, -region_w[i] / 2],
                                 [region_w[i] / 2, -region_w[i] / 2],
                                 [region_w[i] / 2, region_w[i] / 2],
                                 [-region_w[i] / 2, region_w[i] / 2]]);
    }

    // remove the middle 10 mm to thin the backbone (cleaner hull)
    translate([-gauge_len / 2, 0, -eps])
        cube([gauge_len, grip_w + 4, thickness + 2 * eps]);
}
