```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to specimen_t

$fn = 64;

// --- Dimensions (mm) ---
specimen_t   = 3;     // thickness (Z)
gauge_w      = 6;     // gauge section width (Y)
gauge_l      = 50;    // gauge section length (X)
grip_w       = 15;    // grip section width (Y)
grip_l       = 35;    // grip section length (X)
transition_l = 10;    // transition section length (X)
eps          = 0.5;   // cutter overshoot past faces

// Derived
total_l = 2 * grip_l + gauge_l + 2 * transition_l;   // 140 mm

// Width at a given X position (linear between grip and gauge)
function width_at(x) =
    if (x < transition_l)
        grip_w - (grip_w - gauge_w) * x / transition_l;
    else if (x < transition_l + gauge_l)
        gauge_w;
    else
        grip_w + (grip_w - gauge_w) * (x - transition_l - gauge_l) / transition_l;

difference() {
    // Main plate
    translate([-total_l / 2, -grip_w / 2, 0])
        linear_extrude(height = specimen_t)
            polygon(points = [for (i = [0 : 1]) [i * (total_l / 2 - transition_l - gauge_l),
                                                 -width_at(transition_l + gauge_l + i * 0.001) / 2],
                              [i * (total_l / 2 - transition_l - gauge_l),
                               width_at(transition_l + gauge_l + i * 0.001) / 2]]));

    // Central gauge section (slightly overcut in X)
    translate([-gauge_l / 2 - eps, -gauge_w / 2, -eps])
        cube([gauge_l + 2 * eps, gauge_w, specimen_t + 2 * eps]);
}
