```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness   = 4;     // specimen thickness (Z)
total_len   = 140;   // overall length along X
gauge_w     = 8;     // gauge section width (Y)
gauge_len   = 50;    // gauge section length (X)
grip_w      = 19;    // grip section width (Y)
grip_len    = 35;    // grip section length (X)
trans_len   = 10;    // transition section length (X)
eps         = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
half_gauge = gauge_len / 2;
half_grip  = grip_len / 2;
// grip ... trans ... gauge ... trans ... grip
// -55 .. -45 .. 0 .. 45 .. 55
x0 = -half_grip - half_gauge - trans_len;   // left grip start
x1 = -half_gauge;                           // gauge start
x2 = half_gauge;                            // gauge end
x3 = half_grip + half_gauge + trans_len;    // right grip end

// ---------- Model ----------
module dogbone() {
    difference() {
        translate([-x3 / 2, -grip_w / 2, 0])
            linear_extrude(thickness)
                polygon([
                    [x0, -grip_w / 2], [x3, -grip_w / 2],
                    [x3, grip_w / 2],  [x0, grip_w / 2]
                ]);
        translate([-x1 / 2, -gauge_w / 2, eps])
            linear_extrude(thickness - 2 * eps)
                polygon([
                    [x1, -gauge_w / 2], [x2, -gauge_w / 2],
                    [x2, gauge_w / 2],  [x1, gauge_w / 2]
                ]);
        // rounded overlap between grip and gauge
        for (s = [-1, 1])
            translate([s * (half_gauge + trans_len / 2), 0, eps])
                rotate([0, 90, 0])
                    cylinder(h = trans_len, r = (grip_w + gauge_w) / 4, $fn = 64);
    }
}

dogbone();
