```openscad
// Flat dog-bone tensile specimen
// Print orientation: flat on bed, z = 0 upward

// ---------- Parameters ----------
thickness = 3;     // specimen thickness (Z)
total_len = 150;   // overall length along X
gauge_w   = 8;     // gauge section width (Y)
gauge_len = 50;    // gauge section length (X)
grip_w    = 19;    // grip section width (Y)
grip_len  = 35;    // grip section length (X)
trans_len = 15;    // transition section length (X)
eps       = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
half_gauge = gauge_len / 2;
half_grip  = grip_len / 2;
// X position of grip start/end so the two grip sections are symmetric
grip_start = -(total_len / 2 + half_grip + trans_len);
grip_end   =  total_len / 2 + half_grip + trans_len;

// ---------- Model ----------
module width(x) {
    if (x < grip_start || x > grip_end) return grip_w;
    if (x < grip_start + trans_len)
        // linearly grip_w -> gauge_w
        return grip_w + (gauge_w - grip_w) * (x - grip_start) / trans_len;
    if (x < half_gauge) return gauge_w;
    if (x < grip_end - trans_len)
        // linearly gauge_w -> grip_w
        return gauge_w + (grip_w - gauge_w) * (x - grip_end + trans_len) / trans_len;
    return grip_w;
}

difference() {
    // body
    hull() {
        for (s = [-1, 1])
            translate([s * (total_len / 2 - trans_len - grip_len), -width(s * (total_len / 2 - trans_len - grip_len)) / 2, 0])
                cube([grip_len, grip_w, thickness]);
    }
    // central cut leaving the gauge section
    translate([-total_len / 2, -gauge_w / 2, -eps])
        cube([total_len, gauge_w, thickness + 2 * eps]);
}
