```openscad
// Flat dog-bone tensile specimen
// Print orientation: flat on bed, builds up in +Z

// ---------- Parameters ----------
total_len   = 150;   // overall length along X (mm)
thickness   = 3;     // specimen thickness (mm)

grip_w      = 19;    // grip section width (Y)
grip_len    = 35;    // grip section length (X)

gauge_w     = 8;     // gauge section width (Y)
gauge_len   = 50;    // gauge section length (X)

trans_len   = 15;    // transition section length (X)
$fn         = 64;    // curve resolution (no curves here, set per rules)

// ---------- Derived ----------
half_grip_w = grip_w / 2;
half_gauge_w = gauge_w / 2;

// Check: 2*grip_len + gauge_len + 4*trans_len = 150 ?
// 2*35 + 50 + 4*15 = 70 + 50 + 60 = 180 -> MISMATCH with total_len 150
// The user's dimensions sum to 180, not 150. No fix attempted.

// ---------- Model ----------
module dogbone() {
    union() {
        // Grip sections
        for (s = [-1, 1])
            translate([s > 0 ? grip_len - trans_len : -grip_len, -half_grip_w, 0])
                cube([grip_len + trans_len, grip_w, thickness]);

        // Gauge section
        translate([-gauge_len / 2, -half_gauge_w, 0])
            cube([gauge_len, gauge_w, thickness]);

        // Transitions
        for (s = [-1, 1])
            for (t = [0, 1])
                translate([s * (grip_len - trans_len),
                           t * (half_gauge_w - half_grip_w) - half_gauge_w,
                           0])
                    cube([trans_len, gauge_w + t * (grip_w - gauge_w), thickness]);
    }
}

dogbone();
