// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, builds upward in +Z

// ---------- Parameters ----------
part_thickness   = 5;     // part thickness (Z)
outer_diameter   = 60;    // outer rim diameter
rim_width        = 5;     // rim width (radial)
hub_diameter     = 16;    // hub diameter
axle_hole_d      = 8;     // axle hole diameter
spoke_count      = 5;     // number of spokes
spoke_width      = 4;     // spoke width (radial)
first_spoke_ang  = 0;     // first spoke along +X axis (degrees)
cut_extra        = 0.5;   // extra length on cutters past faces
$fn              = 128;   // curve resolution

// ---------- Derived ----------
outer_r = outer_diameter / 2;
hub_r   = hub_diameter / 2;
rim_r   = outer_r - rim_width;   // inner radius of rim ring

// ---------- Model ----------
union() {
    // Outer rim ring
    difference() {
        cylinder(d = outer_diameter, h = part_thickness);
        translate([0, 0, -cut_extra])
            cylinder(d = 2 * rim_r, h = part_thickness + 2 * cut_extra);
    }

    // Hub with axle hole
    difference() {
        cylinder(d = hub_diameter, h = part_thickness);
        translate([0, 0, -cut_extra])
            cylinder(d = axle_hole_d, h = part_thickness + 2 * cut_extra);
    }

    // Spokes from hub to rim
    for (i = [0 : spoke_count - 1]) {
        a = first_spoke_ang + i * 360 / spoke_count;
        translate([hub_r, 0, 0])
            rotate([0, 0, a])
                translate([0, -spoke_width / 2, 0])
                    cube([rim_r - hub_r, spoke_width, part_thickness]);
    }
}
