    translate([0, 0, -eps])
        difference() {
            cylinder(d = hub_d, h = rim_w + 2 * eps);
            translate([0, 0, -eps])
                cylinder(d = axle_hole_d, h = rim_w + 2 * eps + 2);
        }

    // Spokes from hub to rim
    for (i = [0 : spoke_count - 1]) {
        a = spoke_start + i * 360 / spoke_count;
        translate([0, 0, -eps])
            rotate([0, 0, a])
                difference() {
                    translate([0, -spoke_w / 2, 0])
                        cube([wheel_d / 2, spoke_w, rim_w + 2 * eps]);
                    // remove inner half of spoke (from axle hole out to rim)
                    translate([0, -spoke_w / 2, -eps])
                        cylinder(d = hub_d + 4, h = rim_w + 2 * eps + 2);
                }
    }
