// T-shaped nut for aluminium extrusion slot
// Print orientation: flange on XY plane (z = 0), neck builds upward (+Z)

// ---------------- Parameters ----------------
flange_width   = 14;   // flange width along Y (mm)
flange_thick   = 3;    // flange thickness along Z (mm), z = 0..3
neck_width     = 8;    // neck width along Y (mm)
neck_top_z     = 7;    // top of neck along Z (mm)
screw_d        = 5.5;  // central screw hole diameter (mm)
length_x       = 15;   // part length along X (mm)
eps            = 0.5;  // cutter overshoot past faces (mm)
$fn            = 96;   // curve resolution

// ---------------- Model ----------------
difference() {
    // T profile, centred in X and Y
    union() {
        // Bottom flange: -7 to +7 in Y, z = 0..3
        translate([-length_x / 2, -flange_width / 2, 0])
            cube([length_x, flange_width, flange_thick]);
        // Neck: centred on origin in X and Y, z = 3..7
        translate([0, -neck_width / 2, flange_thick])
            cube([neck_width, neck_top_z - flange_thick]);
    }

    // Vertical screw hole through the full height
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = neck_top_z + 2 * eps);
}
