    rotate([90, 0, 0])
        cylinder(d = cross_section_d, r = ring_radius, h = ring_width);

    // A straight cut along the Z axis, centred on the ring.
    // It runs from below z = 0 to above the middle plane, through the full radius.
    translate([0, 0, -cut_extra])
        cylinder(r = ring_radius + cut_extra, h = middle_z + cut_extra);
}
