// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---------------- Parameters ----------------
plate_len   = 50;    // plate length along X (mm)
plate_wid   = 20;    // plate width along Y (mm)
plate_thk   = 3;     // plate thickness along Z (mm)

knuckle_d   = 6;     // knuckle cylinder diameter (mm)
knuckle_n   = 5;     // number of segments along the edge
knuckle_x0  = -plate_len/2 + 10; // x of first segment centre (10 mm segments)
knuckle_y   = plate_wid/2;   // y of knuckle axis (on +Y edge)
knuckle_z   = plate_thk;     // z of knuckle axis (on top face)

pin_d       = 3;     // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments (odd indices)
        for (i = [0 : knuckle_n - 1]) {
            if (i % 2 == 0) {
                translate([knuckle_x0 + i * plate_len/(knuckle_n - 1),
                           knuckle_y, knuckle_z])
                    cylinder(d = knuckle_d, h = 10);
            }
        }
    }

    // Pin hole running along X through every knuckle
    translate([knuckle_x0 - eps, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2 * eps);
}
