    hull() {
        for (i = [0 : points - 1]) {
            rotate([0, 0, i * 360 / points])
                translate([0, 0, 0])
                    union() {
                        // outer point
                        translate([outer_r, 0, 0])
                            cube([outer_r, 2 * outer_r, thickness]);
                        // inner point
                        translate([-inner_r, 0, 0])
                            cube([inner_r, 2 * inner_r, thickness]);
                    }
        }
    }

    // central hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
