// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 upward

// ---- Parameters ----
outer_r   = 35;    // distance of outer points from centre
inner_r   = 17.5;  // distance of inner points from centre
points    = 6;     // number of (outer/inner) point pairs
thickness = 3;     // plate thickness
hole_d    = 6;     // central through-hole diameter
eps       = 0.5;   // cutter overshoot past faces

$fn = 96;

// ---- Model ----
difference() {
    // Star outline: outer points at 0°, 60°... ; inner points at 30°, 90°...
    polygon(points = points * 2,
            draw = true,
            v = concat([for (i = [0 : points - 1])
