// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness   = 3;     // specimen thickness (Z)
total_len   = 110;   // overall length along X
gauge_w     = 8;     // gauge section width (Y)
gauge_len   = 40;    // gauge section length (X)
grip_w      = 19;    // grip section width (Y)
grip_len    = 25;    // grip section length (X)
trans_len   = 10;    // transition section length (X)

$fn = 64;

// ---------- Derived ----------
left_grip_x   = -total_len/2 + grip_len;
right_grip_x  = total_len/2 - grip_len;
gauge_x_start = -gauge_len/2;
gauge_x_end   = gauge_len/2;

// ---------- Model ----------
module dogbone() {
    hull() {
        // Left grip
        translate([-grip_len/2, -grip_w/2, 0])
            cube([grip_len, grip_w, thickness]);
        // Right grip
        translate([grip_len/2, -grip_w/2, 0])
            cube([grip_len, grip_w, thickness]);
        // Gauge section
        translate([gauge_x_start, -gauge_w/2, 0])
            cube([gauge_len, gauge_w, thickness]);
    }
}

difference() {
    dogbone();

    // Clean up transition volumes: cut from each grip a block extending
    // into the gauge, with width changing from grip_w down to gauge_w.
    // The cut runs from z = 0 to z = thickness, so nothing is left
    // coplanar with the faces it cuts.
    for (sx = [-1, 1]) {
        x0 = sx > 0 ? right_grip_x : left_grip_x;
        w0 = grip_w;
        // one step per side: from grip width to gauge width
        // (coordinates run from -1 to 1, so the factor is 0.5)
        for (t = [0 : 0.5 : 1]) {
            w = w0 + (gauge_w - w0) * t;
            translate([x0 + sx * trans_len * t, -w/2, 0])
                cube([trans_len * t, w, thickness]);
        }
    }
}
