// ---------- Modules ----------
module grip_section(len, w) {
    translate([-len / 2, -w / 2, 0])
        cube([len, w, specimen_t]);
}

module transition_section(start_x, end_x, w_start, w_end) {
    // Hull of two end blocks gives a linear width change
    hull() {
        translate([start_x, -w_start / 2, 0])
            cube([eps, w_start, specimen_t]);
        translate([end_x, -w_end / 2, 0])
            cube([eps, w_end, specimen_t]);
    }
}

