union() {
    // Left grip
    grip_section(grip_l, grip_w);
    // Left transition (20 -> 8)
    transition_section(-grip_l, -gauge_l - transition_l, grip_w, gauge_w);
    // Gauge section
    translate([-gauge_l / 2, -gauge_w / 2, 0])
        cube([gauge_l, gauge_w, specimen_t]);
    // Right transition (8 -> 20)
    transition_section(gauge_l + transition_l, grip_l, gauge_w, grip_w);
    // Right grip
    translate([0, 0, 0])
        grip_section(grip_l, grip_w);
