$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 10;    // gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // transition section length (X)
overlap        = 0.5;   // overlap between adjacent sections for clean unions

// ---- Derived ----
x0 = -total_length / 2;   // left end of specimen
w1 = grip_width;          // end grip width
w2 = grip_width + transition_len * (gauge_width - grip_width) / transition_len; // start of gauge (20+15*0/15=20)
w3 = gauge_width;         // gauge width
w4 = w2;                  // end of gauge
w5 = grip_width;          // end grip width

// ---- Sections ----
module end_grip() {
    translate([x0 - overlap, -w1 / 2, 0])
        cube([grip_length + overlap, w1, thickness]);
}

module transition() {
    // linear extrusion of a polygon along X (polygon Y -> world Z)
    rotate([90, 0, 0])
        linear_extrude(height = transition_len)
            polygon([
                [0, w2 / 2],
                [transition_len, w4 / 2],
                [transition_len, w3 / 2],
                [0, w1 / 2]
            ]);
}

module gauge() {
    translate([x0 + grip_length - overlap, -w3 / 2, 0])
        cube([gauge_length + overlap, w3, thickness]);
}

union() {
    end_grip();
    translate([x0 + grip_length, -w2 / 2, 0])
        cube([transition_len, w2, thickness]);
    gauge();
    translate([x0 + grip_length + transition_len, -w4 / 2, 0])
        cube([transition_len, w4, thickness]);
    translate([x0 + total_length / 2 - grip_length, -w5 / 2, 0])
        cube([grip_length + overlap, w5, thickness]);
}
