transition_len  = 15;    // grip-to-gauge transition length (X)
eps            = 0.5;    // cutter overshoot past faces

// ---- Derived ----
x0 = -total_length/2;    // left end of specimen
w(x) =
    if (x < -grip_length + transition_len)
        grip_width + (gauge_width - grip_width) *
            (x + grip_length - transition_len) / transition_len
    else if (x <= -gauge_length/2)
        grip_width
    else if (x <= gauge_length/2)
        gauge_width
    else if (x < total_length/2 - transition_len + grip_length)
        grip_width + (gauge_width - grip_width) *
            (x - (total_length/2 - transition_len + grip_length)) / transition_len
    else
        grip_width;

// ---- Model ----
difference() {
    linear_extrude(height = thickness)
        translate([x0, -14])
            polygon([for (lx = [-total_length/2, total_length/2])
                       [lx, 0]]);   // hull spine along X

    translate([0, 0, -eps])
        linear_extrude(height = thickness + 2*eps)
            polygon([for (lx = [-gauge_length/2, gauge_length/2])
                       [lx, -gauge_width/2],
                    for (lx = [-gauge_length/2, gauge_length/2])
                       [lx, gauge_width/2]]);    // narrow gauge hole
}
