// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 up to part thickness

// ---------- Parameters ----------
wheel_thickness   = 5;    // part thickness (Z)
outer_diameter    = 80;   // outer rim diameter
rim_width         = 4;    // rim width (radial)
hub_diameter      = 16;   // hub diameter
axle_hole_d       = 5;    // axle hole diameter
spoke_count       = 4;    // number of spokes
spoke_width       = 4;    // spoke width (radial and tangential)
spoke_start_angle = 0;    // first spoke along +X axis
cut_extra         = 0.5;  // cutter overshoot past faces
$fn               = 128;  // curve resolution

// ---------- Derived ----------
outer_r = outer_diameter / 2;
hub_r   = hub_diameter / 2;
rim_r   = outer_r - rim_width;   // inner radius of rim ring

// ---------- Model ----------
difference() {
    union() {
        // Outer rim ring
        cylinder(r1 = rim_r, r2 = outer_r, h = wheel_thickness);

        // Central hub with axle hole
        translate([0, 0, -cut_extra])
            difference() {
                cylinder(r = hub_r, h = wheel_thickness + 2 * cut_extra);
                translate([0, 0, -cut_extra])
                    cylinder(d = axle_hole_d, h = wheel_thickness + 2 * cut_extra + 2);
            }
    }

    // Radial spokes from hub to rim
    for (i = [0 : spoke_count - 1]) {
        a = spoke_start_angle + i * 360 / spoke_count;
        translate([hub_r, 0, -cut_extra])
            rotate([0, 0, a])
                difference() {
                    translate([0, -spoke_width / 2, 0])
                        cube([rim_r - hub_r + cut_extra,
                               spoke_width,
                               wheel_thickness + 2 * cut_extra]);
                    // remove overlap with hub (except a thin slice near the edge)
                    translate([0, -spoke_width / 2 + cut_extra, 0])
                        cube([hub_r - cut_extra,
                               spoke_width,
                               wheel_thickness + 2 * cut_extra]);
                }
    }
}
