handle_h0  = rim_z - handle_thick;       // handle bottom face height (z = 11)
handle_h1  = rim_z;                      // handle top face height (z = 15)

// ---------------- Model ----------------
union() {
    // Hollow spherical bowl (lower half only)
    translate([0, 0, rim_z])
        difference() {
            sphere(r = outer_radius);
            translate([0, 0, cut_extra])
                sphere(r = inner_r + 2 * cut_extra);
        }
    // Keep only the lower half of the sphere (z = 0 to rim_z)
    translate([0, 0, -cut_extra])
        difference() {
            hull() {
                translate([0, 0, cut_extra])
                    sphere(r = outer_radius);
                translate([0, 0, -cut_extra])
                    sphere(r = cut_extra);
            }
        }

    // Flat handle along +X, centred on y = 0
    translate([handle_x0, -handle_width / 2, handle_h0])
        cube([handle_x1 - handle_x0, handle_width, handle_thick]);
