```openscad
// Ring weight for a flask neck, printed flat on the bed.
// It is a torus: a round cross-section (circle 8 mm in diameter)
// sweeping around the Z axis on a circle of radius 20 mm.
// The ring is 48 mm across (diameter of the sweep circle x 2),
// rests on z = 0 and has its middle plane at z = 4.

// ---------------- Parameters ----------------
cross_section_d      = 8;    // diameter of the torus cross-section (mm)
sweep_radius         = 20;   // radius of the circle the cross-section traces (mm)
cut_margin           = 0.5;  // extra length for cutting shapes past faces (mm)
$fn                  = 128;  // facet count for round features

// Derived
sweep_diameter       = sweep_radius * 2;              // 40 mm
ring_outer_diameter  = sweep_diameter + cross_section_d;  // 48 mm
ring_area            = (cross_section_d / 2) ** 2 * pi();  // cross-section area

// ---------------- Model ----------------
difference() {
    // The torus body: a cylinder whose axis lies on the 20 mm radius circle
    rotate([0, 0, 45])
        translate([sweep_radius, 0, 0])
            cylinder(d = cross_section_d, h = sweep_diameter);

    // A coaxial void that the ring encloses, running through the part.
    // Its axis is on the bed (z = 0), so the void has a floor at z = 0.
    translate([0, 0, -cut_margin])
        cylinder(d = sweep_diameter + cut_margin * 2,
                 h = cross_section_d + 2 * cut_margin);
}
