$fn           = 96;  // curve resolution

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the +Y edge: 1st, 3rd, 5th segments
        for (i = [0 : knuckle_n - 1]) {
            if (i % 2 == 0) {
                x = (i - (knuckle_n - 1)/2) * knuckle_pitch;
                translate([x, knuckle_y, knuckle_z])
                    cylinder(d = knuckle_d, h = plate_thk + 2*eps);
            }
        }
    }

    // Pin holes along the knuckle axis, through every knuckle
    translate([0, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = knuckle_n * knuckle_pitch + 2*eps);
