    translate([left_grip_end - grip_length, -grip_width/2, 0])
        cube([grip_length, grip_width, thickness]);

    // Right grip
    translate([right_grip_end - grip_length, -grip_width/2, 0])
        cube([grip_length, grip_width, thickness]);

    // Gauge and transitions (for loop: x = -ve to +ve)
    for (x = [0 : transition_len : gauge_length]) {
        w = grip_width + (grip_to_gauge) * x / gauge_length;
        translate([-gauge_length/2 - transition_len + x, -w/2, 0])
            cube([gauge_length/2 + transition_len - x, w, thickness]);
    }
