        // Left grip
        translate([-total_len / 2 + grip_len, -half_grip, 0])
            cube([grip_len, grip_w, thickness]);
        // Right grip
        translate([total_len / 2 - grip_len, -half_grip, 0])
            cube([grip_len, grip_w, thickness]);
        // Gauge section
        translate([-gauge_len / 2, -half_gauge, 0])
            cube([gauge_len, gauge_w, thickness]);
    }

    // Remove overlapping material in transitions
    for (s = [-1, 1]) {
        x0 = s > 0 ? trans_start : -trans_end;
        x1 = s > 0 ? trans_end : -trans_start;
        translate([x0, -half_grip - eps, -eps])
            cube([trans_len + eps, grip_w + 2 * eps, thickness + 2 * eps]);
