    -half_grip - trans_len,   // left grip
    -half_gauge - trans_len,  // left transition
    0,                         // gauge
    half_gauge + trans_len,   // right transition
    half_grip + trans_len     // right grip
];

// ---------- Model ----------
difference() {
    // solid plate
    translate([-total_len / 2, -thickness / 2, 0])
        cube([total_len, thickness, 100]);

    // cut out the two grip blocks and the gauge block
    for (i = [0 : 4]) {
        w = [grip_w, grip_w, gauge_w, grip_w, grip_w][i];
        l = [grip_len, trans_len, gauge_len, trans_len, grip_len][i];
        translate([region_c[i] - l / 2, -w / 2, -eps])
            cube([l, w, thickness + 2 * eps]);
    }
}
