grip_l       = 25;    // grip section length (X)
transition_l = 10;    // transition section length (X)
eps          = 0.5;   // cutter overshoot past faces

// Derived
total_l = 2 * grip_l + gauge_l + 2 * transition_l;   // 110 mm

// Width at a given X position (linear between grip and gauge)
function width_at(x) =
    if (x < transition_l)
        grip_w - (grip_w - gauge_w) * x / transition_l;
    else if (x < transition_l + gauge_l)
        gauge_w;
    else
        grip_w + (grip_w - gauge_w) * (x - transition_l - gauge_l) / transition_l;

difference() {
    // Main plate
    translate([-total_l / 2, -grip_w / 2, 0])
        cube([total_l, grip_w, specimen_t]);

    // Central gauge section (slightly reduced Y to avoid coplanar faces)
    translate([-gauge_l / 2, -gauge_w / 2 - 0.01, 0])
        cube([gauge_l, gauge_w + 0.02, specimen_t]);
}
