    difference() {
        // Outer profile (seen from above), extruded through thickness
        linear_extrude(height = thickness)
            hull() {
                // left grip
                translate([-half_grip - trans_len, -grip_w / 2, 0])
                    cube([grip_len + trans_len, grip_w, thickness]);
                // right grip
                translate([half_grip + trans_len, -grip_w / 2, 0])
                    cube([grip_len + trans_len, grip_w, thickness]);
                // gauge section
                translate([-half_gauge, -gauge_w / 2, 0])
                    cube([gauge_len, gauge_w, thickness]);
            }
    }
