// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 45;   // plate length along X
plate_wid   = 30;   // plate width along Y
plate_thk   = 3;    // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;    // knuckle diameter
knuckle_n   = 3;    // number of knuckles
knuckle_w   = plate_len / knuckle_n;  // 15 mm segment width
knuckle_y   = plate_wid / 2;          // y = 15
knuckle_z   = plate_thk;              // z = 3 (axis on top face)

// ---- Pin hole ----
pin_d       = 2.5;  // pin hole diameter

// ---- Cutting overlap ----
eps         = 0.5;  // extension past cut faces

module plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module knuckles() {
    for (i = [0 : knuckle_n - 1]) {
        x = (i - (knuckle_n - 1)/2) * knuckle_w;
        translate([x, knuckle_y, knuckle_z])
            cylinder(d = knuckle_d, h = 10, $fn = 64);  // 10 mm above plate
    }
}

module pin_holes() {
    for (i = [0 : knuckle_n - 1]) {
        x = (i - (knuckle_n - 1)/2) * knuckle_w;
        translate([x, knuckle_y, knuckle_z - eps])
            cylinder(d = pin_d, h = 10 + 2*eps, $fn = 64);
    }
}

union() {
    plate();
    knuckles();
}

difference() {
    self();
    pin_holes();
}
```

