// Leaf of a pin hinge
// Print orientation: flat plate on bed, knuckles pointing up (+Z)

// ---------------- Parameters ----------------
plate_len   = 50;    // plate length along X (mm)
plate_wid   = 30;    // plate width along Y (mm)
plate_thk   = 3;     // plate thickness along Z (mm)

knuckle_d   = 8;     // knuckle cylinder diameter (mm)
knuckle_z   = 4;     // height of knuckle axis above bed (mm)
knuckle_h   = 16;    // length of knuckle cylinder along X (mm)
knuckle_hole = 3;    // pin hole diameter (mm)

segment_n   = 5;     // number of equal segments along plate length
segment_w   = plate_len / segment_n;  // segment width (10 mm)

eps         = 0.5;   // overshoot for clean boolean cuts (mm)

$fn = 96;            // curve resolution

// ---------------- Derived ----------------
knuckle_count = 3;   // 1st, 3rd, 5th segments have knuckles

// ---------------- Model ----------------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles
    for (i = [0 : knuckle_count - 1]) {
        x = (i % 2) * (segment_w * 2 - segment_w) + segment_w/2;  // 10, 30, 50
        translate([x - knuckle_h/2, plate_wid/2, 0])
            difference() {
