// Flat dog-bone tensile specimen
// Print orientation: flat on bed, builds up in +Z, centred on origin in X/Y

$fn = 64;

// ---- Dimensions (mm) ----
thickness   = 4;     // specimen thickness
total_len   = 140;   // overall length along X
gauge_len   = 50;    // gauge section length
gauge_w     = 6;     // gauge section width (Y)
grip_len    = 35;    // grip section length
grip_w      = 19;    // grip section width (Y)
trans_len   = 10;    // transition section length (each side)
eps         = 0.5;   // cutter overshoot past faces

// ---- Derived ----
half_gauge  = gauge_len / 2;
grip_x0     = -(half_gauge + trans_len - grip_len / 2);   // grip centre offset

module profile() {
    hull() {
        // grip sections
        for (s = [-1, 1])
            translate([s * grip_x0, -grip_w / 2, 0])
                cube([grip_len, grip_w, thickness + 2 * eps]);
        // gauge section
        translate([-half_gauge, -gauge_w / 2, 0])
            cube([gauge_len, gauge_w, thickness + 2 * eps]);
    }
}

difference() {
    linear_extrude(height = thickness) profile();
    // remove a sliver from each grip to avoid coplanar outer faces
    for (s = [-1, 1])
        translate([s * grip_x0 - eps, -grip_w / 2, 0])
            cube([eps, grip_w, thickness + 2 * eps]);
}
