    translate([-total_length / 2 + half_grip, -grip_width / 2, 0])
        cube([grip_length, grip_width, thickness]);

    // Gauge section
    translate([-half_gauge, -gauge_width / 2, 0])
        cube([gauge_length, gauge_width, thickness]);

    // Right grip
    translate([total_length / 2 - half_grip, -grip_width / 2, 0])
        cube([grip_length, grip_width, thickness]);

    // Transitions (15 -> 8 and 8 -> 15)
    for (s = [-1, 1]) {
        x0 = s > 0 ? -half_gauge : half_gauge;
        w0 = gauge_width;
        w1 = grip_width;
        translate([x0 + s * transition_len / 2, -w1 / 2, 0])
            linear_extrude(thickness)
                polygon([
                    [0, -w1 / 2],
                    [transition_len, w1 / 2],
                    [transition_len, -w1 / 2]
                ]);
    }
