        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders on 1st and 3rd segments
        for (i = [0, knuckle_n - 1]) {
            x = -knuckle_pitch * (knuckle_n - 1) / 2 + i * knuckle_pitch;
            translate([x, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + 2*eps);
