    // Pin hole along the knuckle axis through every knuckle
    translate([-knuckle_pitch * (knuckle_n - 1) / 2, knuckle_y, knuckle_z])
        translate([0, 0, -eps])
            cylinder(d = pin_d, h = plate_thk + 2*eps);
