    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles on 1st and 3rd segments only
    for (x = segment_x[0], i = [0]; x <= segment_x[2], i = [i+1];)
        translate([x, knuckle_r, 0])
            rotate([0, 90, 0])
                cylinder(d = knuckle_d, h = knuckle_h + plate_thk);
}

// ---- Pin hole through every knuckle ----
translate([0, knuckle_r, knuckle_z])
    rotate([0, 90, 0])
        cylinder(d = pin_d, h = plate_len + 2*eps, center = true);
