// Leaf of a pin hinge
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Dimensions (mm) ----
plate_len    = 60;   // plate length along X
plate_wid    = 30;   // plate width along Y
plate_thk    = 2.5;  // plate thickness along Z

knuckle_d    = 6;    // knuckle diameter
knuckle_h    = 10;   // knuckle height above plate
knuckle_z0   = 3;    // first knuckle axis height (plate_thk/2 + 1.5)

pin_d        = 2.5;  // pin hole diameter
pin_overlap  = 1;    // how far the pin hole runs into the knuckle

segment_len  = 12;   // length of each X segment along +Y edge
n_segments   = 5;    // number of segments (1, 3, 5 have knuckles)

eps          = 0.5;  // cutter overshoot past faces

// ---- Model ----
difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments
        for (i = [0 : n_segments - 1])
            if (i % 2 == 0)
                translate([-plate_len/2 + i * segment_len, plate_wid/2, 0])
                    cylinder(d = knuckle_d, h = knuckle_h);
    }

    // Pin holes along the axis of each knuckle
    for (i = [0 : n_segments - 1])
        if (i % 2 == 0)
            translate([-plate_len/2 + i * segment_len, plate_wid/2, knuckle_z0])
                translate([0, 0, -eps])
                    cylinder(d = pin_d, h = knuckle_h + 2 * eps - pin_overlap);
}
