// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 up to plate_t

// ---- Parameters ----
outer_r   = 40;   // distance of outer points from centre
inner_r   = 20;   // distance of inner points from centre
point_n   = 5;    // number of points (and inner points)
plate_t   = 4;    // plate thickness
hole_d    = 8;    // central through-hole diameter
eps       = 0.5;  // cutter overshoot past faces

$fn = 96;

// ---- Model ----
difference() {
    // Star outline: outer points at 0,72,... deg, inner points at 36,108,... deg
    hull() {
        for (i = [0 : point_n - 1]) {
            a = i * 360 / point_n;
            translate([outer_r * cos(a), outer_r * sin(a), 0])
                cylinder(h = plate_t, r = outer_r, $fn = 96);
            translate([inner_r * cos(a + 180 / point_n),
                       inner_r * sin(a + 180 / point_n), 0])
                cylinder(h = plate_t, r = inner_r, $fn = 96);
        }
    }
    // Central hole, extends past top and bottom faces
    translate([0, 0, -eps])
        cylinder(h = plate_t + 2 * eps, d = hole_d, $fn = 96);
}
