half_gauge = gauge_len / 2;
half_grip  = grip_len / 2;
// grip ... trans ... gauge ... trans ... grip
// e.g. right grip ends at x = +65, gauge centre at x = 0

// ---------- Model ----------
difference() {
    // Main plate
    translate([-total_len / 2, -thickness / 2, 0])
        cube([total_len, thickness, thickness]);

    // Grip cutouts
    for (s = [-1, 1])
        translate([s * (half_gauge + half_grip + eps), -thickness / 2, 0])
            cube([grip_len + 2 * eps, thickness, thickness]);

    // Gauge cutout (narrow waist)
    translate([-half_gauge, -thickness / 2, 0])
        cube([gauge_len + 2 * eps, thickness, thickness]);

    // Transitions: width changes linearly from grip_w to gauge_w
    for (s = [-1, 1]) {
        x0 = s * (half_gauge + half_grip);   // grip/transition start
        x1 = s * half_gauge;                 // transition end (gauge edge)
        w0 = grip_w;
        w1 = gauge_w;
        // rotate([90,0,0]) maps 2D y -> Z, extrusion -> Y (width)
        rotate([90, 0, 0])
            linear_extrude(height = thickness)
                polygon(points = [
                    [x0 - eps, 0],
                    [x1,      (w0 - w1) * (x1 - x0) / (w0 + w1) / 2 + w0 / 2],
                    [x1 - eps, w1]
                ]);
