// Spoked wheel for a small sample cart
// Print orientation: flat on bed, builds upward in +Z

// ---------- Parameters ----------
wheel_thickness = 5;    // part thickness (Z)
outer_diameter  = 60;   // outer rim diameter
rim_width       = 4;    // rim width (radial)
hub_diameter    = 16;   // hub diameter
axle_hole       = 5;    // axle hole diameter
spoke_count     = 5;    // number of spokes
spoke_width     = 5;    // spoke width (radial)
cut_extra       = 0.5;  // cutter overshoot past faces
$fn             = 128;  // curve resolution

// ---------- Derived ----------
outer_r = outer_diameter / 2;
hub_r   = hub_diameter / 2;
rim_r   = outer_r - rim_width;

// ---------- Model ----------
difference() {
    union() {
        // Outer rim ring
        cylinder(d = outer_diameter, h = wheel_thickness, r = rim_r);

        // Hub with axle hole
        translate([0, 0, -cut_extra])
            cylinder(d = hub_diameter, h = wheel_thickness + 2 * cut_extra);

        // Radial spokes, first along +X axis
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([hub_r, -spoke_width / 2, -cut_extra])
                    cube([outer_r - hub_r, spoke_width, wheel_thickness + 2 * cut_extra]);
