// Powder measuring scoop
// Units: mm. Print orientation: bowl bottom on bed (z = 0), handle extending along +X.

// ---------------- Parameters ----------------
outer_radius   = 12;    // outer radius of spherical bowl
wall_thickness = 2;     // wall thickness of bowl (inner radius = outer - wall)
handle_width  = 8;     // handle width along Y
handle_thick  = 4;     // handle thickness along Z
handle_x0     = 10;    // handle start position along X
handle_x1     = 72;    // handle end position along X
rim_z         = 12;    // rim height (lower hemisphere: z = 0..12)
cut_extra     = 0.5;   // overshoot for clean boolean cuts

$fn = 96;              // facet count for curved surfaces

// ---------------- Model ----------------
union() {
    // Hollow spherical bowl: lower half only
    difference() {
        translate([0, 0, rim_z - wall_thickness])
            sphere(r = outer_radius);
        translate([0, 0, rim_z - wall_thickness - cut_extra])
            sphere(r = outer_radius - wall_thickness);
        // keep only lower half (z <= rim_z), discarding the upper half
        translate([0, 0, -1000])
            cube([outer_radius * 2, wall_thickness * 2, 2 * rim_z]);
    }

    // Flat handle, top face flush with rim (z = 8 to 12)
    translate([handle_x0, -handle_width / 2, rim_z - handle_thick])
        cube([handle_x1 - handle_x0, handle_width, handle_thick]);
}
