// Powder measuring scoop
// Print orientation: handle on the bed, bowl pointing up

$fn = 96;

// ---- Dimensions (mm) ----
bowl_outer_r   = 15;    // outer radius of the spherical bowl
bowl_wall      = 1.5;   // wall thickness of the bowl
handle_len     = 81.5;  // handle length (x = 13.5 to x = 95)
handle_w       = 12;    // handle width (Y)
handle_t       = 3;     // handle thickness (Z)
overlap        = 0.5;   // overlap between handle and bowl for a clean union

// ---- Derived ----
bowl_vr        = bowl_outer_r + bowl_wall;   // vertex radius of the half-sphere
bowl_hole_r    = bowl_outer_r - bowl_wall;   // inner radius of the bowl
handle_z0      = bowl_outer_r - overlap;     // handle bottom height (flush with rim top)

module bowl() {
    difference() {
        // Lower half of the outer sphere, centred at origin, sitting on z = 0
        translate([0, 0, -bowl_vr])
            sphere(r = bowl_vr);
        // Lower half of the pocket, centred at origin, bottom touching the bed
        translate([0, 0, -bowl_hole_r])
            sphere(r = bowl_hole_r);
    }
}

module handle() {
    translate([13.5, -handle_w / 2, handle_z0])
        cube([handle_len, handle_w, handle_t]);
}

union() {
    bowl();
    handle();
}
