        // Flat handle, top face flush with rim
        translate([handle_x0, -handle_width / 2, rim_z - handle_thick])
            cube([handle_x1 - handle_x0, handle_width, handle_thick]);
    }

    // Remove the upper half of the sphere (above z = rim_z - wall_thickness)
    // to leave only the lower half with the given wall thickness
    translate([0, 0, rim_z - wall_thickness - cut_extra])
        cube([outer_radius * 2 + cut_extra,
              outer_radius * 2 + cut_extra,
              wall_thickness + cut_extra]);
}
