    for (i = [0 : knuckle_count - 1])
        if (i % 2 == 0)
            translate([(i - 2) * knuckle_pitch, knuckle_y, knuckle_z])
                translate([0, 0, -eps])
                    cylinder(d = pin_d, h = plate_thk + 2 * knuckle_r + 2 * eps);
