gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 10;    // length of each grip-gauge transition (X)
cut_extra      = 0.5;   // overshoot for clean boolean cuts

// ---- Derived ----
half_gauge = gauge_width / 2;
half_grip  = grip_width / 2;
x0         = -total_length / 2;   // left end of specimen

// Width profile seen from above (piecewise linear)
function width(x) =
    if (x < x0 + grip_length)          grip_width;
    else if (x < x0 + grip_length + transition_len)
        grip_width - (x - (x0 + grip_length)) * (grip_width - gauge_width) / transition_len;
    else if (x < x0 + total_length - transition_len - grip_length)
        gauge_width;
    else if (x < x0 + total_length - grip_length)
        gauge_width + (x - (x0 + total_length - grip_length)) * (grip_width - gauge_width) / transition_len;
    else                               grip_width;

difference() {
    // Main plate
    translate([x0, -half_grip, 0])
        cube([total_length, grip_width, thickness]);

    // Central gauge section, extended past both end faces
    translate([x0 - cut_extra, -half_gauge, -cut_extra])
        cube([gauge_length + 2 * cut_extra, gauge_width, thickness + 2 * cut_extra]);
}
