cut_extra        = 0.5;   // cutter overshoot past faces
$fn              = 128;   // curve resolution

// ---------- Derived ----------
outer_r      = outer_diameter / 2;
hub_r        = hub_diameter / 2;
spoke_len    = outer_r - hub_r;   // spoke runs from hub to rim

// ---------- Model ----------
difference() {
    union() {
        // Outer rim
        cylinder(d = outer_diameter, h = part_thickness);

        // Hub
        translate([0, 0, -cut_extra])
            cylinder(d = hub_diameter, h = part_thickness + 2 * cut_extra);

        // Spokes
        for (i = [0 : spoke_count - 1]) {
            a = first_spoke_ang + i * 360 / spoke_count;
            translate([spoke_len * cos(a), spoke_len * sin(a), -cut_extra])
                cube([spoke_width, spoke_len, part_thickness + 2 * cut_extra]);
        }
    }

    // Axle hole through hub
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole_d, h = part_thickness + 2 * cut_extra);
