first_spoke_ang  = 0;     // first spoke angle (deg, 0 = +X axis)
cut_extra        = 0.5;   // extra length on cutters past faces
$fn              = 128;   // curve resolution

// ---------- Derived ----------
outer_r      = outer_diameter / 2;
rim_inner_r  = outer_r - rim_width;
hub_r        = hub_diameter / 2;
spoke_len    = outer_r - hub_r;   // spoke runs from hub to rim

// ---------- Model ----------
difference() {
    union() {
        // Outer rim
        cylinder(d = outer_diameter, h = part_thickness);

        // Hub
        translate([0, 0, -cut_extra])
            cylinder(d = hub_diameter, h = part_thickness + 2 * cut_extra);

        // Spokes: radial blocks from hub to rim, evenly spaced
        for (i = [0 : spoke_count - 1]) {
            a = first_spoke_ang + i * 360 / spoke_count;
            translate([hub_r, 0, -cut_extra])
                rotate([0, 0, a])
                    cube([spoke_len, spoke_width, part_thickness + 2 * cut_extra]);
        }
    }

    // Axle hole through the hub
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole_d, h = part_thickness + 2 * cut_extra);
}
