            sphere(r = outer_radius);
            translate([0, 0, -eps])
                sphere(r = outer_radius - wall_thickness);
        }
    // Keep only points with z <= rim_z + outer_radius (lower half)
    translate([-(outer_radius + eps), -(outer_radius + eps), 0])
        cube([2 * (outer_radius + eps), 2 * (outer_radius + eps), rim_z + outer_radius]);
