pin_d = 3;          // pin hole diameter (mm)

// ---- Clearances ----
eps = 0.5;          // overshoot for clean boolean cuts (mm)

difference() {
    union() {
        // Base plate, centred in X and Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the 1st, 3rd and 5th segments (odd indices)
        for (i = [0 : knuckle_n - 1]) {
            if ((i + 1) % 2 == 0) continue;  // skip even segments
            x = (i + 0.5) * knuckle_pitch - knuckle_pitch/2;
            translate([x, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = plate_len + 2*eps, $fn = 96);
        }
    }

    // Pin hole along the common axis of all knuckles
    translate([-knuckle_pitch/2, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps, $fn = 96);
}
