        // Upper surface
        linear_extrude(height = thickness)
            hull() {
                for (s = [-1, 1]) {
                    translate([s * (grip_length / 2 + transition_len + gauge_length / 2),
                               -grip_width / 2]) square([grip_length, grip_width]);
                    translate([x0 + s * gauge_length / 2,
                               -gauge_width / 2]) square([gauge_length, gauge_width]);
                }
            }
        // Grip end blocks (overlap into gauge by transition_len)
        for (s = [-1, 1])
            translate([s * (gauge_length / 2 - transition_len / 2),
                       -grip_width / 2]) cube([grip_length + transition_len, grip_width, thickness]);
    }
}

