// Flat dog-bone tensile specimen
// Print orientation: flat on bed, z = 0 upward

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 140;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // length of each grip-to-gauge transition (X)

// ---- Derived ----
eps            = 0.5;   // cutter overshoot past faces

// Width at a given X (piecewise linear)
function w(x) =
    abs(x) <= grip_length/2 ? grip_width :
    abs(x) <= (grip_length + transition_len)/2 ?
        grip_width + (transition_len - abs(x) - grip_length/2) * (gauge_width - grip_width) / transition_len :
    abs(x) <= (total_length - grip_length)/2 ? gauge_width :
        gauge_width + (abs(x) - (total_length - grip_length)/2) * (grip_width - gauge_width) / transition_len;

module profile() {
    pts = [for (x = [-total_length/2 : 1 : total_length/2]) [x, w(x) / 2], [total_length/2, -w(total_length/2)/2]];
    polygon(points = pts);
}

difference() {
    linear_extrude(height = thickness) profile();

    // Thin central relief to avoid coplanar gauge faces
    translate([0, 0, thickness * 0.25])
        linear_extrude(height = eps) profile();
}
