// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 40;    // plate length along X
plate_wid   = 20;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;     // knuckle diameter
knuckle_n   = 5;     // number of segments
knuckle_x0  = -plate_len/2; // first segment centre X
knuckle_y   = 10;    // knuckle axis Y position
knuckle_z   = 3;     // knuckle axis Z position
knuckle_pitch = plate_len/(knuckle_n-1); // 8 mm segment length

// ---- Pin hole ----
pin_d       = 2.5;   // pin hole diameter

// ---- Cutting overlap ----
eps         = 0.5;   // extension past faces for clean differences

difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments
        for (i = [0, 2, 4]) {
            translate([knuckle_x0 + i*knuckle_pitch, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = 10, $fn = 64);
        }
    }

    // Pin hole through every knuckle
    for (i = [0, 2, 4]) {
        translate([knuckle_x0 + i*knuckle_pitch, knuckle_y, knuckle_z - eps])
            cylinder(d = pin_d, h = 10 + 2*eps, $fn = 64);
    }
}
