// ---------------- Derived values ----------------
// Half-width at a given z, linearly interpolated between base and top
half_w(z) = base_size/2 + (top_size/2 - base_size/2) * z / height;

// ---------------- Model ----------------
difference() {
    // Solid frustum: two vertical faces (at x = ±half_w(z), y = ±half_w(z))
    // rotated 45 deg, so their intersection is a square whose sides run parallel to X and Y.
    rotate([90, 0, 45])
        linear_extrude(height = height)
            polygon([
                [-half_w(0), half_w(0)],
                [ half_w(0), half_w(0)],
                [ half_w(0), -half_w(0)],
                [-half_w(0), -half_w(0)],
                [-half_w(height), -half_w(height)],
                [-half_w(height), half_w(height)],
                [ half_w(height), half_w(height)],
                [ half_w(height), -half_w(height)]
            ]);

    // Square pocket cut into the top face, centred, extending past the top surface
    translate([-pocket_size/2, -pocket_size/2, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + overlap]);
