    for (s = [-1, 1])
        translate([s * grip_x0, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

    // Gauge section
    translate([gauge_x0, -gauge_width / 2, 0])
        cube([gauge_length, gauge_width, thickness]);

    // Transitions (linear width change from grip to gauge)
    for (s = [-1, 1]) {
        x0 = s > 0 ? gauge_x0 - transition_len : grip_x0;
        w0 = s > 0 ? gauge_width : grip_width;
        w1 = s > 0 ? grip_width : gauge_width;
        translate([x0, -w0 / 2, 0])
            linear_extrude(thickness)
                polygon([
                    [0, -w0 / 2],
                    [transition_len, -w1 / 2],
                    [transition_len, w1 / 2],
                    [0, w0 / 2]
                ]);
    }
