// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to specimen_t

$fn = 64;

// --- Dimensions (mm) ---
specimen_t   = 3;     // thickness (Z)
gauge_w      = 6;     // gauge section width (Y)
gauge_l      = 50;    // gauge section length (X)
grip_w       = 19;    // grip section width (Y)
grip_l       = 30;    // grip section length (X)
transition_l = 15;    // transition section length (X)
total_l      = 140;   // overall length (X)

// Derived
half_gauge = gauge_l / 2;
half_grip  = grip_l / 2;

difference() {
    // Full shape (overestimates the end blocks)
    union() {
        // Grip sections
        for (sx = [-1, 1])
            translate([sx > 0 ? half_gauge + transition_l : -half_grip - transition_l,
                       -grip_w / 2, 0])
                cube([grip_l, grip_w, specimen_t]);

        // Gauge section
        translate([-half_gauge, -gauge_w / 2, 0])
            cube([gauge_l, gauge_w, specimen_t]);

        // Transition sections (width changes linearly from grip_w to gauge_w)
        for (sx = [-1, 1]) {
            x0 = sx > 0 ? half_gauge : -half_grip - transition_l;
            // rotate([90,0,0]) maps 2D (u,v) -> (x,z), extrude gives Y
            rotate([90, 0, 0])
                linear_extrude(height = specimen_t)
                    polygon(points = [
                        [x0, -grip_w / 2],
                        [x0 + transition_l, -grip_w / 2],
                        [x0 + transition_l, gauge_w / 2],
                        [x0, gauge_w / 2]
                    ]);
        }
    }

    // Remove the overlapping end chunks of the grip blocks so each grip is exactly grip_l
    for (sx = [-1, 1])
        translate([sx * (half_gauge + transition_l + grip_l), -grip_w / 2 - 1, -1])
            cube([grip_l + 2, grip_w + 2, specimen_t + 2]);
}
