// Flat tensile test specimen (dog bone) for testing printed plastic
// Print orientation: flat on bed, builds upward in +Z

// ---------- Parameters ----------
thickness = 4;     // specimen thickness (Z)
total_len = 120;   // overall length along X
gauge_w   = 6;     // gauge section width (Y)
gauge_len = 50;    // gauge section length (X)
grip_w    = 20;    // grip section width (Y)
grip_len  = 25;    // grip section length (X)
trans_len = 10;    // transition section length (X)
eps       = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
half_gauge = gauge_len / 2;   // 25
half_grip  = grip_len / 2;    // 12.5

// ---------- Model ----------
difference() {
    // Outer block
    translate([-total_len / 2, -grip_w / 2, 0])
        cube([total_len, grip_w, thickness]);

    // Central gauge section
    translate([-half_gauge, -gauge_w / 2, eps])
        cube([gauge_len, gauge_w, thickness - 2 * eps]);

    // Grip sections at each end
    for (s = [-1, 1])
        translate([s * half_grip - half_grip, -grip_w / 2, 0])
            cube([grip_len, grip_w, thickness]);

    // Transition sections: width changes linearly from grip_w to gauge_w
    for (s = [-1, 1]) {
        x0 = s * half_grip - half_grip + grip_len;   // grip end / trans start
        // rotate([90,0,0]) maps its 2D y -> Z and extrudes toward +X;
        // the 2D curve runs from x = trans_len to x = gauge_len
        rotate([90, 0, 0])
            linear_extrude(height = trans_len - eps, center = true)
                polygon([
                    [0, (grip_w - gauge_w) * trans_len / 2 + gauge_w],
                    [trans_len - eps, (grip_w - gauge_w) * trans_len / 2 + gauge_w]
                ]);
        translate([s * x0, 0, 0])
            rotate([90, 0, 0])
                linear_extrude(height = trans_len - eps, center = true)
                    polygon([
                        [0, (grip_w - gauge_w) * trans_len / 2 + gauge_w],
                        [trans_len - eps, (grip_w - gauge_w) * trans_len / 2 + gauge_w]
                    ]);
    }
}
