module profile() {
    union() {
        // Gauge section
        translate([-half_gauge, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Grip sections
        for (s = [-1, 1])
            translate([s * (x0 - grip_length / 2), -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);

        // Transitions (width changes linearly from grip 20 -> gauge 6)
        for (t = [transition_len, -transition_len])
            for (s = [-1, 1])
                translate([s * (half_gauge + t), -grip_width / 2, 0])
                    linear_extrude(thickness)
                        polygon([
                            [0, -grip_width / 2],
                            [transition_len, -grip_width / 2],
                            [transition_len, grip_width / 2],
                            [0, grip_width / 2]
                        ]);
    }
}

difference() {
    translate([-total_length / 2, -grip_width / 2, 0])
        cube([total_length, grip_width, thickness]);
    translate([-total_length / 2, -grip_width / 2, 0])
        cube([total_length, grip_width, thickness], profile());
