        translate([-total_length / 2, -thickness / 2, 0])
            linear_extrude(thickness)
                polygon(points = [
                    [-total_length / 2, -grip_width / 2],
                    [total_length / 2, -grip_width / 2],
                    [total_length / 2, grip_width / 2],
                    [x0, grip_width / 2],
                    [x0, -grip_width / 2],
                    [-x0, -grip_width / 2],
                    [-x0, grip_width / 2],
                    [-total_length / 2, grip_width / 2]
                ]);

module gauge_section() =
    translate([-gauge_length / 2, -gauge_width / 2, 0])
        linear_extrude(thickness)
            rectangle(size = [gauge_length, gauge_width]);

