// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 upward

// ---- Parameters ----
wheel_od      = 80;    // outer diameter of rim
rim_width     = 4;     // rim width (radial)
hub_d         = 14;    // hub outer diameter
axle_d        = 6;     // axle hole diameter
spoke_count   = 5;     // number of spokes
spoke_w       = 4;     // spoke width
spoke_start   = 0;     // angle of first spoke (deg, +X axis)
eps           = 0.5;   // cutter overshoot past faces
$fn           = 128;   // curve resolution

// ---- Derived ----
rim_id = wheel_od - 2 * rim_width;   // inner diameter of rim ring
t      = 5;                          // part thickness

// ---- Model ----
union() {
    // Outer rim
    difference() {
        cylinder(d = wheel_od, h = t);
        translate([0, 0, -eps])
            cylinder(d = rim_id, h = t + 2 * eps);
    }

    // Hub with axle hole
    translate([0, 0, -eps])
        difference() {
            cylinder(d = hub_d, h = t + 2 * eps);
            translate([0, 0, -eps])
                cylinder(d = axle_d, h = t + 2 * eps + 2);
        }

    // Spokes: radial bars from hub to rim
    for (i = [0 : spoke_count - 1]) {
        a = spoke_start + i * 360 / spoke_count;
        translate([hub_d / 2 - 1, 0, -eps])
            rotate([0, 0, a])
                difference() {
                    translate([0, -spoke_w / 2, 0])
                        cube([wheel_od / 2, spoke_w, t + 2 * eps]);
                    // remove overlap with rim to avoid coplanar faces
                    translate([wheel_od / 2 - rim_width - 1, -spoke_w / 2, 0])
                        cube([rim_width + 2, spoke_w, t + 2 * eps]);
                }
    }
}
